package com.resumeanalyzer.controller;
import com.resumeanalyzer.dto.AnalysisResponseDto; import com.resumeanalyzer.dto.JobMatchDto; import com.resumeanalyzer.service.JobMatchService; import com.resumeanalyzer.service.ResumeService; import lombok.RequiredArgsConstructor; import org.springframework.http.MediaType; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.util.List;
@RestController @RequestMapping("/api/v1/resumes") @RequiredArgsConstructor public class ResumeController { private final ResumeService resumes; private final JobMatchService jobs; @PostMapping(value="/upload",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) AnalysisResponseDto upload(@RequestPart("file") MultipartFile file,@RequestPart(value="jobDescription",required=false) String jobDescription){return resumes.uploadAndAnalyze(file,jobDescription);} @GetMapping("/job-matches") List<JobMatchDto> jobMatches(){return jobs.findMatches();} }
